// JavaScript string semantics the widget has to reproduce exactly, because the
// hand-over was written by JavaScript and the parity fixture was generated by
// it (ios-lifer-widgets, schema.md sections 6.3 and 7).
//
// * Comparison is by UTF-16 code unit, which is what JS `<` does. Swift's own
//   `String <` compares by Unicode canonical ordering, which differs, so no
//   ordering in Logic/ uses it.
// * `String.prototype.trim`'s set is spelled out (ECMA-262 WhiteSpace plus
//   LineTerminator). NOT `CharacterSet.whitespacesAndNewlines`, which also
//   strips U+0085 (and would make a name ending in it fold differently here
//   than in the app), and NOT Rust's `is_whitespace`. The Rust and TypeScript
//   validators use the same list.

import Foundation

enum JSText {
    /// ECMA-262 WhiteSpace + LineTerminator, every one a single UTF-16 unit.
    static func isTrimSpace(_ u: UInt16) -> Bool {
        switch u {
        case 0x0009, 0x000A, 0x000B, 0x000C, 0x000D, 0x0020, 0x00A0, 0x1680,
             0x2000...0x200A, 0x2028, 0x2029, 0x202F, 0x205F, 0x3000, 0xFEFF:
            return true
        default:
            return false
        }
    }

    /// `s.trim()`, over UTF-16 code units.
    static func trim(_ units: ArraySlice<UInt16>) -> ArraySlice<UInt16> {
        var lo = units.startIndex
        var hi = units.endIndex
        while lo < hi, isTrimSpace(units[lo]) { lo += 1 }
        while hi > lo, isTrimSpace(units[hi - 1]) { hi -= 1 }
        return units[lo..<hi]
    }

    static func trim(_ s: String) -> String {
        let u = Array(s.utf16)
        return string(trim(u[...]))
    }

    static func string<C: Collection>(_ units: C) -> String where C.Element == UInt16 {
        String(decoding: units, as: UTF16.self)
    }

    /// JS `a < b` / `a > b`: lexicographic by UTF-16 code unit.
    static func compare(_ a: String, _ b: String) -> Int {
        var ia = a.utf16.makeIterator()
        var ib = b.utf16.makeIterator()
        while true {
            switch (ia.next(), ib.next()) {
            case (nil, nil): return 0
            case (nil, _): return -1
            case (_, nil): return 1
            case let (x?, y?):
                if x != y { return x < y ? -1 : 1 }
            }
        }
    }

    /// UTF-16 length, the unit every string bound in this feature is measured in.
    static func length(_ s: String) -> Int { s.utf16.count }
}
